import*as THREE from'three';import{Port,materials}from'../../core/index.js';import{mesh,FACE,portQuaternion}from'../../modeling/parts.js';import{spec}from'./dimensions.js';
export function grove(host){const frame=new THREE.Group();frame.name='SSR actual black open-top Grove DIN socket';frame.position.fromArray(spec.grove.position);frame.quaternion.copy(FACE.bottom);host.body.add(frame);const plastic=materials.plastic(spec.grove.color,{roughness:.7}),metal=materials.metal(0xb6b6a5,{roughness:.45}),box=(s,p,n,m=plastic)=>mesh(frame,new THREE.BoxGeometry(...s),m,p,'SSR Grove '+n);for(const sign of[-1,1]){box([.65,5.2,6.3],[sign*4.675,0,-3.15],'side wall');box([.7,.6,3.2],[sign*3.85,2.3,-4.7],'guide rail');box([.6,.45,1.2],[sign*3.65,2.375,-1.8],'latch shoulder');}box([8.7,.65,6.3],[0,-2.275,-3.15],'floor');box([8.7,4.55,.65],[0,.325,-5.975],'deep dielectric rear wall');box([4.8,.45,2.3],[0,2.375,-4.5],'locking bridge');const contacts=[],tails=[];for(let i=0;i<4;i++){contacts.push(box([.42,.42,4.5],[(i-1.5)*2,.2,-3.6],'actual contact '+(i+1),metal));const tail=new THREE.Group();tail.name='SSR Grove actual right-angle solder tail '+(i+1);frame.add(tail);mesh(tail,new THREE.BoxGeometry(.42,.42,2.0),metal,[(i-1.5)*2,.2,-6.7],'SSR Grove rearward solder leg');mesh(tail,new THREE.BoxGeometry(.42,3.2,.42),metal,[(i-1.5)*2,-1.4,-7.7],'SSR Grove actual plated-through solder tail');tails.push(tail);}const port=host.add(new Port({id:'grove',label:'PORT.B · physical DIN socket',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,5.2],pins:[{n:1,name:'GND',color:'black'},{n:2,name:'5V',color:'red'},{n:3,name:'DIN',color:'yellow'},{n:4,name:'NC',color:'white'}],pinGrid:{cols:4,rows:1,pitch:2,center:[0,.2],order:col=>4-col},meta:{role:'visual-connector',face:'bottom',scope:'Four real contact labels,physical attachment and cable pose only.No voltage,current,SSR switching,electrical routing or firmware behavior'}}));return{frame,contacts,tails,port};}
export function terminal(host){const frame=new THREE.Group();frame.name='SSR exact own orange HT3.96 four-contact receiving board header';frame.position.fromArray(spec.terminal.position);host.body.add(frame);const orange=materials.plastic(0xf49a38,{roughness:.72}),metal=materials.metal(0xb8bdb0,{roughness:.43}),box=(s,p,n,m=orange)=>mesh(frame,new THREE.BoxGeometry(...s),m,p,'SSR terminal '+n);const sides=[];for(const sign of[-1,1]){sides.push(box([.6,8.8,7.2],[sign*8.3,-4.4,.6],'actual full side wall'));box([.8,1.1,2.4],[sign*7.4,-2.2,1.6],'molded guide/latch');}const floor=box([16,8.8,.6],[0,-4.4,-2.7],'actual cavity floor'),roof=box([16,8.8,.6],[0,-4.4,3.9],'actual projecting roof'),rear=box([16,.6,6.0],[0,-8.5,.6],'deep closed dielectric rear wall'),contacts=[],tails=[],rails=[];for(const[i,x]of spec.terminal.pinX.entries()){contacts.push(box([.5,5.3,.5],[x,-4.15,-.4],'real board male contact '+(i+1),metal));const tail=new THREE.Group();tail.name='SSR terminal actual bent solder tail '+(i+1);frame.add(tail);mesh(tail,new THREE.BoxGeometry(.5,3.2,.5),metal,[x,-8.1,-.4],'SSR terminal rearward metal tail');mesh(tail,new THREE.BoxGeometry(.5,.5,3.2),metal,[x,-9.4,-2.0],'SSR terminal actual plated-through solder tail');tails.push(tail);}for(const x of[-3.96,0,3.96])rails.push(box([.42,5.8,.55],[x,-4.2,-2.1],'low channel-separating rail'));const port=host.add(new Port({id:'terminal',label:'U122 actual four-pole removable terminal',connector:'ht3.96-4p',position:spec.terminal.position,hitSize:[17,1,7.2],pins:spec.terminal.names.map((name,i)=>({n:i+1,name})),pinGrid:{cols:4,rows:1,pitch:3.96,center:[0,-.4],order:col=>col+1},meta:{role:'visual-connector',face:'top',source:spec.terminal.labelEvidence,scope:'Physical four-contact attachment only.No SSR state,voltage/current,load,continuity,electrical routing or firmware behavior'}}));return{frame,sides,floor,roof,rear,contacts,tails,rails,port};}
